<?php
use App\DonorType; use App\Models\Donor; use Illuminate\Database\Eloquent\Builder; use Illuminate\Support\Facades\Gate; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component; use Livewire\WithPagination;
new #[Title('Donors')] class extends Component { use WithPagination; public string $search=''; public ?int $editing=null; public string $firstName=''; public string $lastName=''; public string $email=''; public string $phone=''; public string $type='visitor'; public string $notes=''; public function mount():void{Gate::authorize('viewAny',Donor::class);} public function edit(int $id):void{$d=Donor::findOrFail($id);Gate::authorize('update',$d);$this->editing=$id;$this->firstName=$d->first_name;$this->lastName=$d->last_name;$this->email=$d->email??'';$this->phone=$d->phone??'';$this->type=$d->donor_type->value;$this->notes=$d->notes??'';} public function save():void{$d=$this->editing?Donor::findOrFail($this->editing):new Donor;Gate::authorize($d->exists?'update':'create',$d->exists?$d:Donor::class);$v=$this->validate(['firstName'=>['required','max:100'],'lastName'=>['nullable','max:100'],'email'=>['nullable','email','max:255',Rule::unique('donors')->ignore($d)],'phone'=>['nullable','max:50'],'type'=>['required',Rule::enum(DonorType::class)],'notes'=>['nullable','max:5000']]);$d->fill(['first_name'=>$v['firstName'],'last_name'=>$v['lastName']?:'','email'=>$v['email']?:null,'phone'=>$v['phone']?:null,'donor_type'=>$v['type'],'notes'=>$v['notes']?:null,'is_anonymous'=>false])->save();$this->reset(['editing','firstName','lastName','email','phone','notes']);$this->type='visitor';session()->flash('success',__('Donor saved.'));} public function donors(){return Donor::withCount('donations')->withSum(['donations as completed_total'=>fn($q)=>$q->completed()],'amount')->withMin('donations','donated_at')->withMax('donations','donated_at')->when($this->search,fn(Builder $q)=>$q->where(fn(Builder $q)=>$q->where('first_name','like','%'.$this->search.'%')->orWhere('last_name','like','%'.$this->search.'%')->orWhere('email','like','%'.$this->search.'%')->orWhere('phone','like','%'.$this->search.'%')))->latest()->paginate(15);} }; ?>
<div class="mx-auto w-full max-w-7xl space-y-6"><x-admin.page-header :title="__('Donors')" :description="__('Manage private donor profiles and giving history.')" :eyebrow="__('Giving management')"/><div class="grid gap-6 lg:grid-cols-3"><form wire:submit="save" class="space-y-3 rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{$editing?__('Edit donor'):__('Add donor')}}</flux:heading><div class="grid grid-cols-2 gap-3"><flux:input wire:model="firstName" :label="__('First name')"/><flux:input wire:model="lastName" :label="__('Last name')"/></div><flux:input wire:model="email" type="email" :label="__('Email')"/><flux:input wire:model="phone" :label="__('Phone')"/><flux:select wire:model="type" :label="__('Type')">@foreach(DonorType::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:textarea wire:model="notes" :label="__('Internal notes')"/><flux:button type="submit" variant="primary" class="w-full">{{__('Save donor')}}</flux:button></form><section class="overflow-hidden rounded-xl border bg-white lg:col-span-2 dark:border-zinc-800 dark:bg-zinc-900"><div class="border-b p-4 dark:border-zinc-800"><flux:input wire:model.live.debounce.300ms="search" :label="__('Search donors')"/></div><table class="w-full text-sm"><thead><tr><th class="px-5 py-3 text-left">{{__('Donor')}}</th><th class="px-5 py-3">{{__('Donations')}}</th><th class="px-5 py-3">{{__('Completed total')}}</th><th></th></tr></thead><tbody>@foreach($this->donors() as $d)<tr class="border-t dark:border-zinc-800"><td class="px-5 py-4"><strong>{{$d->full_name}}</strong><p class="text-xs text-slate-500">{{$d->email}} · {{$d->phone}}</p></td><td class="px-5 py-4 text-center">{{$d->donations_count}}</td><td class="px-5 py-4 text-center">{{number_format((float)$d->completed_total,2)}}</td><td class="px-5 py-4 text-right"><flux:button :href="route('donors.show',$d)" size="sm" wire:navigate>{{__('Open')}}</flux:button><flux:button wire:click="edit({{$d->id}})" size="sm">{{__('Edit')}}</flux:button></td></tr>@endforeach</tbody></table><div class="p-4">{{$this->donors()->links()}}</div></section></div></div>
